import unittest
from ledger import summarize
class Casefold(unittest.TestCase):
 def test_default_preserves_names(self):
  self.assertEqual(summarize(["Oak:2","oak:3"]),{"Oak":2,"oak":3})
 def test_ascii_merge(self):
  self.assertEqual(summarize([" Oak :2","oak:3"],casefold=True),{"oak":5})
 def test_unicode_expansion(self):
  self.assertEqual(summarize(["Straße:2","STRASSE:4"],casefold=True),{"strasse":6})
 def test_iterator_and_comments(self):
  self.assertEqual(summarize(iter(["# comment",""," Σ :1","ς:3"]),casefold=True),{"σ":4})
 def test_invalid_still_rejected(self):
  with self.assertRaises(ValueError):summarize(["oak:-1"],casefold=True)

import unittest
from ledger import summarize
class LedgerTests(unittest.TestCase):
 def test_repeated_names_add(self):
  self.assertEqual(summarize(["oak:2","oak:3","ash:0"]),{"oak":5,"ash":0})
 def test_trim(self):
  self.assertEqual(summarize(["  oak : 2  "]),{"oak":2})
 def test_comments_and_empty(self):
  self.assertEqual(summarize(["","  "," # note","ash:1"]),{"ash":1})
 def test_unicode_name(self):
  self.assertEqual(summarize(["café:4","café:1"]),{"café":5})
 def test_empty_input(self):
  self.assertEqual(summarize([]),{})
 def test_negative_count(self):
  with self.assertRaises(ValueError):summarize(["oak:-1"])
 def test_empty_name(self):
  with self.assertRaises(ValueError):summarize([":1"])
 def test_malformed(self):
  for row in ["oops","a:x","a:1:2"]:
   with self.subTest(row=row),self.assertRaises(ValueError):summarize([row])

def summarize(lines, *, casefold=False):
    totals = {}
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if ":" not in stripped:
            raise ValueError("malformed record")
        name, count_text = stripped.split(":", 1)
        name = name.strip()
        count_text = count_text.strip()
        if not name:
            raise ValueError("empty name")
        try:
            count = int(count_text)
        except ValueError as exc:
            raise ValueError("invalid count") from exc
        if count < 0:
            raise ValueError("negative count")
        key = name.casefold() if casefold else name
        totals[key] = totals.get(key, 0) + count
    return totals
